head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf72020";
scwin.statusChange = false;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf72020.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd, ipt_updateYn, insertYn

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "btn_saveBubJohang", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "btn_useChkBubJohang", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_relLawNo", fn: function () { return String(String((dma_pageContext.get("relLawNo") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $(document).ready(function() {
                frame.Title = "관련법규조항 변경";
        });
        await scwin.tx_fn_searchBubJohang();
        if ((String(((dma_pageContext.get("ipt_updateYn") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_updateYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_updateYn") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_updateYn") ?? "")))) === 'Y') {
            await $c.win.alert("저장되었습니다.");
        } else {
            if ((String(((dma_pageContext.get("insertYn") ?? "")) == null ? '' : ((dma_pageContext.get("insertYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("insertYn") ?? "")) == null ? '' : ((dma_pageContext.get("insertYn") ?? "")))) === 'Y') {
                await $c.win.alert("등록되었습니다.");
            }
        }
        if ($c.util.getComponent('ipt_johang').getValue().length === 0) {
            setBtnDisable($('#removeSpan'));
        } else {
            (($c.util.getComponent('slc_junmoon')) && ($c.util.getComponent('slc_junmoon')).setDisabled ? ($c.util.getComponent('slc_junmoon')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        }
        frame.Title = "관련법규조항 변경";

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf72020.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_saveBubJohang();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf72020.searchForm_onsubmit' }); }
};

