/**
 * @method
 * @name __on_enter_10_ipt_searchtext
 * @description on enter 10 ipt searchtext 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.__on_enter_10_ipt_searchtext = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.tx_fn_searchBubJohang() }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf72020.__on_enter_10_ipt_searchText' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_saveBubJohang
 * @description save Bub Johang 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_saveBubJohang = async function () {
    const sbmOptions = {
        id: "tx_fn_saveBubJohang",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_saveBubJohangReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

